3. В файле `index.js` необходимо импортировать необходимые пакеты и настроить бота:

```javascript
const { Client, GatewayIntentBits } = require('discord.js');
const { version } = require('./package.json');
const { versionCheck } = require('./utils/versionCheck');
const { CommandHandler } = require('./handlers/commandHandler');

require('dotenv').config();

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.on('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  const commandHandler = new CommandHandler(interaction);
  await commandHandler.execute(commandName);
});

async function main() {
  try {
    await versionCheck();
    await client.login(process.env.TOKEN);
  } catch (error) {
    console.error(error);
    process.exit(1);
  }
}

main();
```

4. Следующим шагом необходимо создать файл `commandHandler.js` в директории `handlers` и настроить обработчик команд:

```javascript
const { MessageEmbed } = require('discord.js');

class CommandHandler {
  constructor(interaction) {
    this.interaction = interaction;
  }

  async execute(commandName) {
    if (commandName === 'ban') {
      await this.handleBan();
    } else {
      this.interaction.reply({
        content: 'Unknown command!',
        ephemeral: true,
      });
    }
  }

  async handleBan() {
    const { guild, member, options } = this.interaction;

    if (!guild.me.permissions.has('BAN_MEMBERS')) {
      return this.interaction.reply({
        content: 'I don\'t have the ban members permission!',
        ephemeral: true,
      });
    }

    const targetMember = await guild.members.fetch(options.getMember('user'));

    if (targetMember.id === this.interaction.user.id) {
      return this.interaction.reply({
        content: 'You can\'t ban yourself!',
        ephemeral: true,
      });
    }

    await guild.bans.create(targetMember.user);

    this.interaction.reply({
      embeds: [
        new MessageEmbed()
          .setTitle('Ban successful')
          .setDescription(`Successfully banned ${targetMember.user.tag}.`)
          .setColor('#ff0000')
      ],
    });
  }
}

module.exports = CommandHandler;
```

5. Создайте файл `versionCheck.js` в корневой директории проекта и добавьте в него следующий код, который проверит версию пакетов и выведет предупреждение в консоль, если обнаружит неподдерживаемую версию:

```javascript
const { version: packageVersion } = require('./package.json');

function versionCheck() {
  const { version: libraryVersion } = require('discord.js');
  const { version: nodeVersion } = process.versions;

  if (parseFloat(libraryVersion.split('.')[0]) > 14) {
    console.warn(
      `Discord.js library version ${libraryVersion} is not supported by this bot. Please update to version 14 or lower.`
    );
  }

  if (parseFloat(nodeVersion.split('.')[0]) > 16) {
    console.warn(
      `Node.js version ${nodeVersion} is not supported by this bot. Please use Node.js version 16 or lower.`
    );
  }

  console.log(`Using Discord.js version ${libraryVersion}`);
  console.log(`Using Node.js version ${nodeVersion}`);
  console.log(`Using package version ${packageVersion}`);
}

module.exports = versionCheck;
```

6. Наконец, создайте файл `index.ts` в директории `commands` и добавьте в него следующий код, который определяет слэш-команду `ban`:

